<?php
namespace App\Http\Controllers\Sales;use App\Http\Controllers\Controller;use App\Models\{CorporateAccount,LocalPurchaseOrder};use Illuminate\Http\Request;
class CorporateController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('sales.companies',['companies'=>CorporateAccount::where('property_id',$p)->latest()->paginate(30),'lpos'=>LocalPurchaseOrder::where('property_id',$p)->with('company')->latest()->limit(50)->get()]);}public function store(Request $r){$d=$r->validate(['name'=>'required|max:180','code'=>'required|max:30','tin'=>'nullable|max:50','email'=>'nullable|email','phone'=>'nullable|max:50','contact_person'=>'nullable|max:120','credit_limit'=>'nullable|numeric|min:0','credit_days'=>'nullable|integer|min:0','default_discount_percent'=>'nullable|numeric|min:0|max:100']);CorporateAccount::create([...$d,'property_id'=>auth()->user()->property_id]);return back()->with('success','Corporate account created.');}public function lpo(Request $r){$d=$r->validate(['corporate_account_id'=>'required|exists:corporate_accounts,id','lpo_number'=>'required|max:80','lpo_date'=>'nullable|date','authorised_amount'=>'required|numeric|min:0.01','notes'=>'nullable|string']);LocalPurchaseOrder::create([...$d,'property_id'=>auth()->user()->property_id]);return back()->with('success','LPO recorded.');}}
